bg=5
out=[[bg]*7 for _ in range(19)]
def place_block(r0,color,pattern):
    for i in range(5):
        for j in range(5):
            out[r0+i][1+j]=color
    for i,row in enumerate(pattern):
        for j,is_hole in enumerate(row):
            if is_hole:
                out[r0+1+i][2+j]=bg
place_block(1,6,[[1,0,1],[1,1,1],[1,0,0]])
place_block(7,9,[[1,1,1],[0,1,0],[1,0,1]])
place_block(13,1,[[0,1,1],[1,1,0],[1,1,1]])
print(len(out), [len(r) for r in out])
print('\n'.join(' '.join(map(str,r)) for r in out))
